function loadEnv(filePath) { const values = {}; for (const line of fs.readFileSync(filePath, 'utf8').split(/\r?\n/)) { const match = line.match(/^([A-Za-z_][A-Za-z0-9_]*)=(.*)$/); if (!match) continue; let value = match[2].trim(); if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) value = value.slice(1, -1); values[match[1]] = value } return values }
function plainText(html) { return html.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&amp;/g, '&').replace(/&#0?39;|&apos;/g, "'").replace(/&quot;/g, '"').replace(/&ndash;|&#8211;/g, '–').replace(/&mdash;|&#8212;/g, '—').replace(/&nbsp;|&#160;/g, ' ').replace(/\s+/g, ' ').trim() }
async function fetchResponse(url, options = {}, attempts = 4) { let lastError; for (let attempt = 1; attempt <= attempts; attempt += 1) { try { const response = await fetch(url, {...options, headers: {'user-agent': 'BahaBuddyResearch/1.0 (content-ops@bahabuddy.com)', ...(options.headers || {})}}); if (response.ok) return response; if (![429, 500, 502, 503, 504].includes(response.status) || attempt === attempts) throw new Error(`Research source failed: ${url} (${response.status})`); lastError = new Error(`Research source retry: ${url} (${response.status})`) } catch (error) { lastError = error; if (attempt === attempts) throw new Error(`Research source failed after retries: ${url}: ${String(error)}`) } await new Promise((resolve) => setTimeout(resolve, attempt * 1200)) } throw lastError || new Error(`Research source failed after retries: ${url}`) }
async function fetchText(url) { return plainText(await (await fetchResponse(url)).text()) }
async function fetchManagedBuffers() { const entries = []; for (const [key, definition] of Object.entries(managedAssetDefinitions)) { const buffer = fs.existsSync(definition.localPath) ? fs.readFileSync(definition.localPath) : Buffer.from(await (await fetchResponse(definition.url)).arrayBuffer()); const checksum = crypto.createHash('sha256').update(buffer).digest('hex'); if (checksum !== definition.checksum) throw new Error(`Managed review image checksum changed for ${definition.url}: ${checksum}`); entries.push({key, ...definition, buffer}); await new Promise((resolve) => setTimeout(resolve, 250)) } return entries }
async function urlStatus(url, attempts = 3) { let lastError; for (let attempt = 1; attempt <= attempts; attempt += 1) { try { const response = await fetch(url, {method: 'HEAD', headers: {'user-agent': 'Mozilla/5.0 (compatible; BahaBuddyResearch/1.0)'}}); return {url, status: response.status, ok: response.ok, contentType: response.headers.get('content-type'), contentLength: response.headers.get('content-length')} } catch (error) { lastError = error; if (attempt < attempts) await new Promise((resolve) => setTimeout(resolve, attempt * 1000)) } } return {url, status: 0, ok: false, error: String(lastError)} }
function reference(id, key = id.replace(/[^a-z0-9]+/gi, '-').slice(0, 90)) { return {_type: 'reference', _key: key, _ref: id} }
function references(ids, prefix) { return [...new Set(ids)].map((id, index) => reference(id, `${prefix}-${index + 1}`)) }
function mergeReferences(current = [], ids, prefix) { const byId = new Map(current.filter((item) => item?._ref).map((item) => [item._ref, item])); for (const [index, id] of [...new Set(ids)].entries()) if (!byId.has(id)) byId.set(id, reference(id, `${prefix}-${index + 1}-${id.replace(/[^a-z0-9]+/gi, '-').slice(-28)}`)); return [...byId.values()] }
function appendOnce(current = '', addition = '') { const base = current.trim(); const extra = addition.trim(); return !extra || base.includes(extra) ? base : `${base} ${extra}`.trim() }
function stripMeta(document) { if (!document) return document; const {_rev, _createdAt, _updatedAt, ...rest} = document; return rest }
function comparable(value) { if (Array.isArray(value)) return value.map(comparable); if (value && typeof value === 'object') return Object.fromEntries(Object.keys(value).filter((key) => !['_rev', '_createdAt', '_updatedAt'].includes(key) && value[key] !== undefined).sort().map((key) => [key, comparable(value[key])])); return value }
function differs(current, planned) { return JSON.stringify(comparable(current)) !== JSON.stringify(comparable(planned)) }
function diffPaths(current, planned, prefix = '') { const left = comparable(current); const right = comparable(planned); if (JSON.stringify(left) === JSON.stringify(right)) return []; if (Array.isArray(left) || Array.isArray(right) || !left || !right || typeof left !== 'object' || typeof right !== 'object') return [prefix || '$']; const keys = [...new Set([...Object.keys(left), ...Object.keys(right)])].sort(); return keys.flatMap((key) => diffPaths(left[key], right[key], prefix ? `${prefix}.${key}` : key)) }
function reviewPlan({cadenceDays, relationship, reviewScope, nextAction, attention = false, method = 'webpage_review', triggers = ['publisher_url_or_scope_change']}) { return {_type: 'researchSourceReviewPlan', plannedAt: checkedAt, reviewOwner: 'Baha Buddy Content Operations', workflowStatus: attention ? 'attention_required' : 'scheduled', freshnessStatus: attention ? 'needs_recheck' : 'current', cadenceBand: cadenceDays <= 30 ? '30_day' : cadenceDays <= 90 ? '90_day' : cadenceDays <= 180 ? '180_day' : cadenceDays <= 365 ? 'annual' : 'long_term', cadenceDays, sourceRelationship: relationship, verificationMethod: method, changeTriggers: triggers, reviewScope, nextAction} }
function block(key, text) { return {_type: 'block', _key: key, style: 'normal', markDefs: [], children: [{_type: 'span', _key: `${key}-span`, text, marks: []}]} }
function locationReview({ids, notes, operation = 'not_established', access = 'unresolved', status = 'identity_without_point', decision = 'not_applicable'}) { return {_type: 'placeLocationReview', checkedAt, reconciliationStatus: status, candidates: [], evidenceSources: references(ids, 'location-source'), locationConfidence: 'low', operationEvidenceStatus: operation, accessEvidenceStatus: access, reviewDecision: decision, notes} }
function travelerReview({ids, notes, responsible = 'unresolved', operation = 'unresolved', access = 'unresolved', accessibility = 'not_published', copy = 'identity_only'}) { return {_type: 'placeTravelerReadinessReview', checkedAt, nextReviewAt: nextOperationalReviewAt, overallStatus: 'blocked', responsibleSourceStatus: responsible, operationStatus: operation, accessStatus: access, safetyStatus: 'not_established', accessibilityStatus: accessibility, copyStatus: copy, mediaStatus: 'no_approved_media', deliveryDecision: 'blocked', sources: references(ids, 'readiness-source'), notes} }
function contentReview({ids, notes, mediaPolicyIds = [sourceIds.mediaBoundary], accessibility = 'not_found_in_reviewed_sources', foundation = 'identity_only', mediaEvidence = 'no_candidate_media', mediaRights = 'unknown_or_unverified', alt = 'no_approved_image'}) { const components = [['identity', 'partial', 'The reviewed record supports an identity lead only.', 'Resolve exact identity, destination, duplicate, category, and accountable source before a canonical change.'], ['description', 'blocked', 'Evidence is insufficient for complete traveler copy.', 'Obtain current responsible context before drafting public copy.'], ['operation_access', 'blocked', 'Current operation, route, restrictions, assistance, and fallback are incomplete.', 'Verify date-specific operation and access with the responsible operator or authority.'], ['safety', 'missing', 'No complete feature-specific safety and emergency package is established.', 'Verify hazards, supervision, communications, response, and traveler limitations.'], ['accessibility', 'missing', 'No complete responsible feature-level accessibility statement is established.', 'Obtain route, surface, transfer, restroom, sensory, service-animal, assistance, and evacuation details.'], ['media', mediaEvidence === 'rights_cleared' ? 'partial' : 'blocked', mediaEvidence === 'rights_cleared' ? 'A rights-documented review image exists, but placement and alt text remain unapproved.' : 'No exact current place image is approved for delivery.', 'Complete identity, age, release, crop, attribution, alt-text, and placement review.'], ['traveler_copy', 'blocked', 'The evidence gates do not form a delivery-safe package.', 'Keep all channels closed until every gate and a separate editorial approval pass.']].map(([component, status, evidenceSummary, nextAction], index) => ({_type: 'placeCopyComponentReview', _key: `component-${index + 1}-${component}`, component, status, evidenceSummary, nextAction})); return {_type: 'placeContentReadinessReview', checkedAt, nextReviewAt: nextOperationalReviewAt, overallStatus: 'blocked', accessibilityEvidenceStatus: accessibility, accessibilitySources: references(ids, 'content-source'), accessibilityBoundary: 'A road, beach, cave, hill, church, vessel, airport feature, or source silence does not establish end-to-end accessibility. Missing evidence is not proof that a place is inaccessible.', copyFoundationStatus: foundation, copyComponents: components, mediaEvidenceStatus: mediaEvidence, mediaRightsStatus: mediaRights, mediaPolicySources: references(mediaPolicyIds, 'media-policy-source'), altTextStatus: alt, publicCopyDecision: 'blocked', notes} }
function fact({id, title, topic, claim, guidance, ids}) { return {_id: id, _type: 'islandFact', title, destination: reference(destinationId, 'destination-long-island'), topic, claim, travelerGuidance: guidance, sources: references(ids, 'source'), checkedAt, nextReviewAt: nextOperationalReviewAt, volatility: 'operational', confidence: 'high', verificationStatus: 'source_verified', channels: [], editorNotes: 'Review-only evidence. This fact does not approve publication, a Supabase change, a coordinate, provider, route, schedule, operation, media asset, accessibility claim, safety claim, or traveler delivery.'} }

const pageUrls = {island: urls.island, bnt: urls.bntConception, iss: urls.issPage, aerial: urls.aerialPage, deans: urls.deansPage, stPauls: urls.stPaulsPage, stPeter: urls.stPeterPage, locator: urls.locatorPage}
const pageEntries = await Promise.all(Object.entries(pageUrls).map(async ([key, url]) => [key, await fetchText(url)]))
