  islandIdentity: /Welcome to Long Island/i.test(pageText.island),
  islandSaysThirdDeepest: /third deepest blue hole in the world/i.test(pageText.island),
  islandAirports: /Deadman.?s Cay Airport/i.test(pageText.island) && /Stella Maris Airport/i.test(pageText.island),
