if (!liveHeroStatus || (liveHeroStatus.status !== 0 && (!liveHeroStatus.ok || !liveHeroStatus.contentType?.startsWith('image/')))) throw new Error(`Published hero changed: ${JSON.stringify(liveHeroStatus)}`)
